-- Additive metadata only: historical events and the existing transmission catalog remain unchanged.
CREATE TABLE calendar_exam_details(event_id TEXT PRIMARY KEY REFERENCES calendar_events(id),exam_type TEXT NOT NULL CHECK(exam_type IN('AUTO','MOTO')));
CREATE TABLE calendar_exam_instructor_vehicles(event_id TEXT NOT NULL,user_id TEXT NOT NULL,vehicle_id TEXT NOT NULL,vehicle_name TEXT NOT NULL,transmission TEXT NOT NULL DEFAULT '',PRIMARY KEY(event_id,user_id),UNIQUE(event_id,vehicle_id),FOREIGN KEY(event_id,user_id) REFERENCES calendar_event_instructors(event_id,user_id),FOREIGN KEY(event_id,vehicle_id) REFERENCES calendar_event_vehicles(event_id,vehicle_id));
CREATE TABLE calendar_exam_participant_departures(event_id TEXT NOT NULL,participant_key TEXT NOT NULL,depart_from_school INTEGER NOT NULL CHECK(depart_from_school IN(0,1)),PRIMARY KEY(event_id,participant_key),FOREIGN KEY(event_id,participant_key) REFERENCES calendar_event_participants(event_id,participant_key));
